import{_ as a,o,c as l,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph QoS Refinements for Background Operations Using MClock","description":"","frontmatter":{"title":"Ceph QoS Refinements for Background Operations Using MClock","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","QoS Optimization","MClock Algorithm","Distributed Storage","Ceph Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_QoS_Refinements_for_Background_Operations_Using_MClock.md","filePath":"posts/2023/Ceph_QoS_Refinements_for_Background_Operations_Using_MClock.md","lastUpdated":1780459816000}'),t={name:"posts/2023/Ceph_QoS_Refinements_for_Background_Operations_Using_MClock.md"};function r(c,e,n,s,h,p){return o(),l("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph中m-clock算法的qos优化" tabindex="-1">会议主题：Ceph中M clock算法的QoS优化 <a class="header-anchor" href="#会议主题-ceph中m-clock算法的qos优化" aria-label="Permalink to &quot;会议主题：Ceph中M clock算法的QoS优化&quot;">​</a></h4><h4 id="参会人员-ceph研发团队成员" tabindex="-1">参会人员：Ceph研发团队成员 <a class="header-anchor" href="#参会人员-ceph研发团队成员" aria-label="Permalink to &quot;参会人员：Ceph研发团队成员&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="会议内容概述" tabindex="-1">会议内容概述： <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述：&quot;">​</a></h4><p>本次会议深入讨论了Ceph中使用M clock算法对后台操作进行QoS（服务质量）优化的方法。M clock算法是一种用于IO资源分配的算法，在Ceph的SEF模块中被使用。会议详细介绍了M clock的工作原理、与之前使用的WPQ（加权优先队列）的对比、以及M clock的优化和测试结果。</p><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>M clock算法介绍</strong>：</p><ul><li>M clock是一种用于IO资源分配的算法，主要用于Ceph中的SEF模块。</li><li>通过三个参数（reservation、limit、weight）控制IO资源的分配。</li></ul></li><li><p><strong>与WPQ的对比</strong>：</p><ul><li>WPQ是之前Ceph OSDs使用的调度器，每个操作都有一个优先级和成本。</li><li>WPQ缺乏资源分配能力、无法区分不同类型的操作，且需要大量配置选项来控制后台操作。</li></ul></li><li><p><strong>M clock的优化</strong>：</p><ul><li>调整了M clock的成本模型，使其更加动态，能够反映操作的实际IO大小。</li><li>优化了M clock的内置配置文件，使其更加用户友好。</li></ul></li><li><p><strong>测试结果</strong>：</p><ul><li>在内部实验室环境中进行的测试显示，M clock在恢复操作和客户端操作方面表现优于WPQ。</li><li>在恢复操作方面，M clock的性能提升显著，且客户端操作的延迟更低。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续优化M clock的成本模型和配置文件。</li><li>计划在更大规模的环境中进行测试，以验证M clock的性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>在更大规模的环境中测试M clock的性能。</li><li>继续优化M clock的配置文件，使其更加用户友好。</li><li>准备将M clock的相关优化合并到Ceph的下一次版本更新中。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议详细讨论了Ceph中M clock算法的QoS优化，通过与WPQ的对比，展示了M clock在性能和用户友好性方面的优势。团队将继续进行测试和优化，以确保M clock能够在实际生产环境中稳定高效地运行。</p>',15)])])}const k=a(t,[["render",r]]);export{_ as __pageData,k as default};
